{"content":"package words_test

import (
	"errors"
	"fmt"
	"io"
	"reflect"
	"strings"
	"testing"

	"example.com/words/words"
)

func mustTopK(t *testing.T, input string, k int, stop []string) []words.WordCount {
	t.Helper()
	got, err := words.TopK(strings.NewReader(input), k, stop)
	if err != nil {
		t.Fatalf("TopK error: %v", err)
	}
	return got
}

func check(t *testing.T, got []words.WordCount, want []words.WordCount) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestBasicCountsAndTieBreak(t *testing.T) {
	got := mustTopK(t, "The cat sat on the mat. The cat!", 10, nil)
	check(t, got, []words.WordCount{
		{"cat", 2}, {"the", 2}, {"mat", 1}, {"on", 1}, {"sat", 1},
	})
	// k smaller than distinct count
	check(t, mustTopK(t, "The cat sat on the mat. The cat!", 2, nil),
		[]words.WordCount{{"cat", 2}, {"the", 2}})
	// k larger than distinct count: return all
	check(t, mustTopK(t, "a b a", 5, nil),
		[]words.WordCount{{"a", 2}, {"b", 1}})
}

func TestCaseFolding(t *testing.T) {
	got := mustTopK(t, "Don't don't DON'T", 10, nil)
	check(t, got, []words.WordCount{{"don't", 3}})
}

func TestStopWords(t *testing.T) {
	got := mustTopK(t, "the THE The a b the", 10, []string{"THE", "a"})
	check(t, got, []words.WordCount{{"b", 1}, {"the", 3}})
}

